// Recharts observes every intermediate pixel during a layout resize. Batching
// that observer work keeps chart-heavy pages (especially Dashboard) responsive
// while the navigation rail is moving. A caller can still opt out with
// debounce={0} when an immediate resize is genuinely needed.
function ResponsiveContainer({ debounce = 180, ...props }) {
  return <RechartsResponsiveContainer {...props} debounce={debounce} />;
}

/* ----------------------------- constants ----------------------------- */

const SESSIONS = ["Sydney", "Tokyo", "London", "NYC AM", "NYC PM", "Off Hours"];
const isUsDaylightSavingDate = (value) => {
  const matched = String(value || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const now = new Date();
  const year = matched ? Number(matched[1]) : now.getUTCFullYear();
  const month = matched ? Number(matched[2]) : now.getUTCMonth() + 1;
  const day = matched ? Number(matched[3]) : now.getUTCDate();
  const firstSunday = (monthIndex) => {
    const firstDay = new Date(Date.UTC(year, monthIndex, 1)).getUTCDay();
    return 1 + ((7 - firstDay) % 7);
  };
  const secondSundayMarch = firstSunday(2) + 7;
  const firstSundayNovember = firstSunday(10);
  if (month < 3 || month > 11) return false;
  if (month > 3 && month < 11) return true;
  if (month === 3) return day >= secondSundayMarch;
  return day < firstSundayNovember;
};
const entrySessionFromOpenTime = (value, date) => {
  const match = String(value || "").match(/^(\d{1,2}):(\d{2})/);
  if (!match) return "";
  const minutes = Number(match[1]) * 60 + Number(match[2]);
  const newYorkDaylightSaving = isUsDaylightSavingDate(date);
  const newYorkAmStart = (newYorkDaylightSaving ? 12 : 13) * 60;
  const newYorkPmStart = (newYorkDaylightSaving ? 16 : 17) * 60;
  const newYorkClose = (newYorkDaylightSaving ? 21 : 22) * 60;
  // A trade has one session label. During an overlap, the active London/Tokyo
  // or New York label takes priority so reporting stays mutually exclusive.
  if (minutes >= 22 * 60) return "Sydney";
  if (minutes < 8 * 60) return "Tokyo";
  if (minutes < newYorkAmStart) return "London";
  if (minutes < newYorkPmStart) return "NYC AM";
  if (minutes < newYorkClose) return "NYC PM";
  return "Off Hours";
};
const normalizeSession = (value) => ({ "Asia": "Tokyo", "NY AM": "NYC AM", "NY PM": "NYC PM" }[value] || value);
const MOODS = ["Confident", "Neutral", "Fear", "FOMO", "Revenge", "Disciplined", "Anxious", "Excited"];
const DEFAULT_MISTAKE_TAGS = [
  "Overtrading", "Early Exit", "No Stop Loss", "Revenge Trade", "FOMO Entry",
  "Sized Too Big", "Sized Too Low", "Missed Entry", "Moved Stop", "Chased Entry",
  "Ignored Rules", "Bad Timing",
];
const allMistakeTags = (customTags = []) => [
  ...DEFAULT_MISTAKE_TAGS,
  ...customTags.filter((tag) => !DEFAULT_MISTAKE_TAGS.some((preset) => preset.toLowerCase() === String(tag).toLowerCase())),
];
const customInstrumentSymbol = (instrument) => typeof instrument === 'string' ? instrument : instrument?.symbol;
const normalizedCustomInstruments = (values = []) => {
  const seen = new Set();
  return values.map((item) => {
    const symbol = normalizeInstrument(customInstrumentSymbol(item));
    const group = INSTRUMENT_GROUPS.includes(item?.group) ? item.group : instrumentGroup(symbol);
    return { symbol, group };
  }).filter(({symbol}) => symbol && !DEFAULT_INSTRUMENTS.some((preset) => sameInstrument(preset, symbol))).filter(({symbol}) => {
    if (seen.has(symbol)) return false;
    seen.add(symbol); return true;
  });
};
