function JournalHeaderSearch({ account, markups, reviews, onNavigate }) {
  const [query, setQuery] = useState("");
  const [focused, setFocused] = useState(false);
  const inputRef = useRef(null);
  useEffect(() => {
    const shortcut = (event) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); inputRef.current?.focus(); }
      if (event.key === "Escape") { setQuery(""); setFocused(false); inputRef.current?.blur(); }
    };
    window.addEventListener("keydown", shortcut);
    return () => window.removeEventListener("keydown", shortcut);
  }, []);
  const records = [
    ...(account.trades || []).map((trade) => ({id:`trade-${trade.id}`,page:"tradelog",title:`${trade.asset || "Trade"} · ${trade.date || ""}`,kind:"Trade",text:[trade.context,trade.notes,trade.entryType,trade.strategy].filter(Boolean).join(" · ")})),
    ...markups.map((markup) => ({id:`markup-${markup.id}`,page:"markups",title:`${markup.instrument || "Markup"} · ${markup.date || ""}`,kind:"Markup",text:[markup.bias,markup.notes,markup.structure].filter(Boolean).join(" · ")})),
    ...reviews.map((review) => ({id:`review-${review.id}`,page:"reviews",title:`Review · ${review.date || ""}`,kind:"Review",text:[review.notes,review.lesson,review.summary].filter(Boolean).join(" · ")}))
  ];
  const matches = query.trim() ? records.filter((record) => `${record.title} ${record.text}`.toLowerCase().includes(query.trim().toLowerCase())) : [];
  return <div className="tj-header-search" onBlur={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false); }}>
    <Search size={14} aria-hidden="true"/><input ref={inputRef} aria-label="Search trades, markups, notes" placeholder="Search trades, markups, notes..." value={query} onFocus={() => setFocused(true)} onChange={(event) => setQuery(event.target.value)}/><kbd>⌘K</kbd>
    {focused && query.trim() && <div className="tj-header-search-results" role="region" aria-label="Journal search results"><small>{matches.length} matching records in this journal</small>{matches.slice(0,8).map((record) => <button type="button" key={record.id} onClick={() => {setQuery("");setFocused(false);onNavigate(record.page);}}><span>{record.kind}</span><strong>{record.title}</strong>{record.text && <p>{record.text}</p>}</button>)}{!matches.length && <p>No matching trades, markups, or notes.</p>}</div>}
  </div>;
}
const JOURNAL_PATHS = Object.freeze({...Object.fromEntries(NAV.map(({ id }) => [id, `/${id === NAV[2].id ? `${id.slice(0, 5)}-${id.slice(5)}` : id === NAV[3].id ? id.slice(0, -1) : id}`])),journal:'/journal-hub'});
const LEGACY_JOURNAL_PATH = `/${['j', 'o', 'u', 'r', 'n', 'a', 'l'].join('')}`;
const JOURNAL_PAGES_BY_PATH = Object.freeze({ ...Object.fromEntries(Object.entries(JOURNAL_PATHS).map(([page, path]) => [path, page])), [LEGACY_JOURNAL_PATH]: NAV[0].id });
const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July",
  "August", "September", "October", "November", "December"];
const MONTH_ABBR = ["JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"];
const DOW = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

const uid = () => Math.random().toString(36).slice(2, 10);
// Cloud trade and markup rows use UUID primary keys. Keep the general short
// UI-id helper above for temporary rows, but give newly created persisted
// entries a retry-safe UUID before their first save.
const persistentEntryId = () => globalThis.crypto?.randomUUID?.()
  || 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (token) => {
    const value = Math.floor(Math.random() * 16);
    return (token === 'x' ? value : (value & 3) | 8).toString(16);
  });
const backtestStorageKey = (userId, scope = 'profile') => `aaicorefx:backtest-trades:${userId}:${scope}`;
const readStoredBacktestTrades = (userId, scope) => {
  try {
    const saved = JSON.parse(window.localStorage.getItem(backtestStorageKey(userId, scope)) || "[]");
    return Array.isArray(saved) ? saved : [];
  } catch { return []; }
};
// Old device-only tests used the account ID as their storage suffix. Merge
// those already-local records into the profile view without touching the
// workspace keys, so the migration remains recoverable and repeatable.
const readBacktestTrades = (userId, accounts = []) => {
  const seen = new Set();
  return ['profile', ...accounts.map(account => account.id)].flatMap(scope => readStoredBacktestTrades(userId, scope)).filter(trade => {
    const key = String(trade?.id || JSON.stringify(trade));
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};
const cTraderOpeningIsUnknown = (trade) => /Imported cTrader position #.*\[close-only\]/i.test(trade?.context || "") && !trade?.time;
const cTraderOpeningWasEnteredManually = (trade) => /\[opening-time:manual\]/i.test(trade?.context || "");
const NavSymbol = ({ src, className = "" }) => <span className={`tj-nav-symbol tj-nav-symbol-mask ${className}`.trim()} style={{'--nav-symbol-image': `url("${src}")`}} aria-hidden="true" />;
const uuid = () => globalThis.crypto?.randomUUID?.() || "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (character) => {
  const value = Math.random() * 16 | 0;
  return (character === "x" ? value : (value & 0x3) | 0x8).toString(16);
});
let activeRegionalPreferences = { timezone: "Africa/Accra", dateFormat: "DD/MM/YYYY", timeFormat: "12" };
const setActiveRegionalPreferences = (preferences = {}) => {
  activeRegionalPreferences = {
    timezone: preferences.timezone || "Africa/Accra",
    dateFormat: ["DD/MM/YYYY", "MM/DD/YYYY", "YYYY-MM-DD"].includes(preferences.dateFormat) ? preferences.dateFormat : "DD/MM/YYYY",
    timeFormat: preferences.timeFormat === "24" ? "24" : "12",
  };
};
const formatDate = (value) => {
  if (!value) return "Date not set";
  const match = String(value).match(/^(\d{4})-(\d{2})-(\d{2})/);
  let year, month, day;
  if (match) [, year, month, day] = match;
  else {
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return "Date not set";
    const parts = new Intl.DateTimeFormat("en-CA", { timeZone: activeRegionalPreferences.timezone, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(date);
    const part = (type) => parts.find((item) => item.type === type)?.value;
    year = part("year"); month = part("month"); day = part("day");
  }
  if (activeRegionalPreferences.dateFormat === "MM/DD/YYYY") return `${month}/${day}/${year}`;
  if (activeRegionalPreferences.dateFormat === "YYYY-MM-DD") return `${year}-${month}-${day}`;
  return `${day}/${month}/${year}`;
};
const formatMonthYear = (value) => {
  const match = String(value || "").match(/^(\d{4})-(\d{2})/);
  if (!match) return "Date not set";
  const [, year, month] = match;
  return activeRegionalPreferences.dateFormat === "YYYY-MM-DD" ? `${year}-${month}` : `${month}/${year}`;
};
const regionalNowParts = (date = new Date()) => {
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone: activeRegionalPreferences.timezone, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(date);
  const part = (type) => parts.find((item) => item.type === type)?.value;
  return { year: part("year"), month: part("month"), day: part("day"), hour: part("hour"), minute: part("minute") };
};
const todayISO = () => { const { year, month, day } = regionalNowParts(); return `${year}-${month}-${day}`; };
const localDateISO = (date = new Date()) => { const { year, month, day } = regionalNowParts(date); return `${year}-${month}-${day}`; };
const nowTime = () => { const { hour, minute } = regionalNowParts(); return `${hour}:${minute}`; };
const formatTime = (time) => {
  if (!time) return "Time not set";
  const [hours, minutes] = String(time).slice(0, 5).split(":").map(Number);
  if (!Number.isFinite(hours) || !Number.isFinite(minutes)) return "Time not set";
  if (activeRegionalPreferences.timeFormat === "24") return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
  const suffix = hours >= 12 ? "PM" : "AM";
  return `${((hours + 11) % 12) + 1}:${String(minutes).padStart(2, "0")} ${suffix}`;
};
let activeMoneyCurrency = "USD";
const normalizeCurrency = (currency) => ACCOUNT_CURRENCIES.some((item) => item.code === currency) ? currency : "USD";
const setActiveMoneyCurrency = (currency) => { activeMoneyCurrency = normalizeCurrency(currency); };
const currencySymbol = (currency = activeMoneyCurrency) => ACCOUNT_CURRENCIES.find((item) => item.code === normalizeCurrency(currency))?.symbol || "$";
const accountInitial = (name) => String(name || "A").trim().charAt(0).toUpperCase() || "A";
const fmtMoney = (n, currency = activeMoneyCurrency) => {
  const v = Number(n) || 0;
  const sign = v > 0 ? "+" : v < 0 ? "-" : "";
  return `${sign}${currencySymbol(currency)}${Math.abs(v).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
};
const fmtMoneyShort = (n, currency = activeMoneyCurrency) => {
  const v = Number(n) || 0;
  const sign = v > 0 ? "+" : v < 0 ? "-" : "";
  return `${sign}${currencySymbol(currency)}${Math.abs(v).toLocaleString(undefined, { maximumFractionDigits: 0 })}`;
};
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const importedAccountBaseNote = "[Imported account base]";
const financeTradingImpact = (movement) => movement.type === "deposit" ? (movement.note?.startsWith(importedAccountBaseNote) ? 0 : movement.amount) : movement.source === "trading" ? -movement.amount : 0;
const currentTradeNetPnl = (account, trade) => {
  const activeIds = new Set(activeBalances(account).map((balance) => balance.id));
  const results = (trade.balanceResults || []).filter((result) => activeIds.has(result.balanceId));
  return results.length ? results.reduce((sum, result) => sum + Number(result.netPnl ?? ((Number(result.grossPnl) || 0) - (Number(result.commission) || 0) - (Number(result.swap) || 0))), 0) : Number(trade.pnl || 0);
};
const accountWithCurrentTradeTotals = (account) => account ? { ...reconcileImportedBases(account), trades:(account.trades || []).map((trade) => ({ ...trade, pnl:currentTradeNetPnl(account, trade) })) } : account;
const balanceTradePnl = (account, balanceId) => (account.trades || []).reduce((sum, trade) => {
  if (!balanceId) return sum + currentTradeNetPnl(account, trade);
  const result = (trade.balanceResults || []).find((item) => item.balanceId === balanceId);
  return sum + (result ? balanceResultNetPnl(result) : 0);
}, 0);
const financeMovementBelongsToBalance = (account, movement, balanceId) => {
  if (!balanceId || movement.balanceId === balanceId) return true;
  // Finance history recorded before multi-account targeting belongs to the
  // original account, which becomes Account 1 after conversion.
  return !movement.balanceId && activeBalances(account)[0]?.id === balanceId;
};
// `accounts.balance` is the latest saved balance for a workspace. It must not
// be used as an opening figure and then have every trade added again. Prefer
// the balance records' immutable starting amounts whenever they exist.
const tradingOpeningBalance = (account, balanceId = null) => {
  const balances = activeBalances(account);
  if (balanceId) return Number(balances.find((balance) => balance.id === balanceId)?.startingBalance ?? account?.balance ?? 0) || 0;
  if (balances.length) return balances.reduce((sum, balance) => sum + (Number(balance.startingBalance) || 0), 0);
  return Number(account?.balance) || 0;
};
const financeTotals = (account, balanceId = null) => {
  const movements = (account.financeMovements || []).filter((movement) => financeMovementBelongsToBalance(account, movement, balanceId));
  const movementTotal = movements.reduce((sum, movement) => sum + financeTradingImpact(movement), 0);
  const tradeTotal = balanceTradePnl(account, balanceId);
  const tradingBalance = tradingOpeningBalance(account, balanceId) + tradeTotal + movementTotal;
  const savings = savingsForBalance(account, balanceId).reduce((sum, item) => sum + financeSavingsBalance(account, item.id), 0);
  const deposits = movements.filter((item) => item.type === "deposit").reduce((sum, item) => sum + item.amount, 0);
  const withdrawals = movements.filter((item) => item.type === "withdrawal").reduce((sum, item) => sum + item.amount, 0);
  return { tradingBalance, savings, totalCapital: tradingBalance + savings, deposits, withdrawals, movementTotal };
};
const norm = (v, max) => clamp((v / max) * 100, 0, 100);
const formatRatio = value => value === Infinity ? '∞' : value.toFixed(2);
const formatAccountBasePercent = value => {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return "—";
  return `${numeric >= 0 ? "+" : ""}${numeric.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}%`;
};
const classify = (pnl, cap) => (Math.abs(pnl) <= cap ? "be" : pnl > 0 ? "win" : "loss");
const RUNNING_TRADE_MARKER = "[aaicorefx-running-trade]";
const isRunningTrade = (trade) => {
  const accountResults = trade?.balanceResults || [];
  // A multi-account trade is closed when at least one selected account has a
  // recorded result. Older rows may still carry the previous open marker.
  if (accountResults.some((result) => result?.grossPnl !== "" && result?.grossPnl != null)) return false;
  return trade?.pnl === null || trade?.pnl === "" || String(trade?.context || "").includes(RUNNING_TRADE_MARKER);
};
const tradeNote = (trade) => String(trade?.context || "").replace(RUNNING_TRADE_MARKER, "").trim();
const closedTrades = (trades) => (Array.isArray(trades) ? trades : []).filter((trade) => trade && !isRunningTrade(trade));
const tradeRiskReward = (trade) => Number(trade?.pnl) < 0 ? -1 : Math.max(0, Number(trade?.rr) || 0);
const tradeTimestamp = (date, time) => {
  if (!date || !time) return null;
  const match = String(time).trim().match(/^(\d{1,2}):(\d{2})(?:\s*([AaPp][Mm]))?$/);
  if (!match) return null;
  let hours = Number(match[1]);
  const minutes = Number(match[2]);
  const meridiem = match[3]?.toLowerCase();
  if (meridiem) hours = hours % 12 + (meridiem === "pm" ? 12 : 0);
  const value = new Date(`${date}T${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}:00`).getTime();
  return Number.isFinite(value) ? value : null;
};
const tradeDurationMinutes = (trade) => {
  const opened = tradeTimestamp(trade?.date, trade?.time);
  const closed = tradeTimestamp(trade?.closeDate || trade?.date, trade?.closeTime);
  if (opened == null || closed == null || closed < opened) return null;
  return Math.round((closed - opened) / 60000);
};
const formatTradeDuration = (trade) => {
  const minutes = tradeDurationMinutes(trade);
  if (minutes == null) return trade?.heldFor || "—";
  if (minutes < 60) return `${minutes}m`;
  const days = Math.floor(minutes / 1440);
  const hours = Math.floor((minutes % 1440) / 60);
  const remainder = minutes % 60;
  const parts = days ? [`${days}d`, `${hours}h`] : [`${hours}h`];
  if (remainder) parts.push(`${remainder}m`);
  return parts.join(" ");
};
const clsColor = (cls) => (cls === "win" ? "tj-green" : cls === "loss" ? "tj-red" : "tj-blue");
// Win-rate percentage system: >50% green, 30-50% muted theme amber, <30% red.
// Bars retain their existing colors so the percentage is the only changing part.
const wrColorClass = (wr) => (wr > 50 ? "tj-green" : wr >= 30 ? "tj-wr-yellow" : "tj-red");
const wrBarClass = (wr) => (wr > 50 ? "tj-bar-green" : wr >= 30 ? "tj-bar-yellow" : "tj-bar-red");
const UI_COLORS = { primary: "var(--tj-green)", danger: "var(--tj-red)", warning: "var(--tj-amber)", info: "var(--tj-blue)", purple: "var(--tj-purple)" };
const CHART_TICK = { fill: "var(--tj-chart-text)", fontSize: 13 };
const CHART_TOOLTIP_STYLE = { background: "var(--tj-tooltip-bg)", color: "var(--tj-text)", border: "1px solid var(--tj-border)", borderRadius: 8, fontSize: 14, boxShadow: "var(--tj-shadow)" };
const wrHex = (wr) => (wr > 50 ? UI_COLORS.primary : wr >= 30 ? UI_COLORS.warning : UI_COLORS.danger);

