  const [selectedBalanceId, setSelectedBalanceId] = useState(() => activeBalances(account)[0]?.id || null);
  const [singleConversionWarning, setSingleConversionWarning] = useState(false);
  const [challengeDraft, setChallengeDraft] = useState(null);
  const [savingSettings, setSavingSettings] = useState(false);
  // Shell v2: on desktop, Account settings is a side panel. Closing slides it out first.
  const [accountPanelOpen, setAccountPanelOpen] = useState(true);
  const accountCloseTimer = useRef(0);
  useEffect(() => () => window.clearTimeout(accountCloseTimer.current), []);
  const draftReward=challengeDraft?.rewardRatio ?? challenge.state.automation?.rewardRatio;
  const draftAdaptiveRisk=challengeDraft?.adaptiveRiskPct ?? challenge.state.automation?.adaptiveRiskPct ?? 1;
  const draftAdaptiveDrawdown=challengeDraft?.adaptiveDrawdownPct ?? challenge.state.automation?.adaptiveDrawdownPct ?? 10;
  const draftChallenge = {
    ...challenge, saving: savingSettings,
    state: challengeDraft ? {...challenge.state, activeLevel: challengeDraft.level, automation: {...challenge.state.automation, mode: challengeDraft.mode, levelCount: challengeDraft.levelCount,rewardRatio:challengeDraft.rewardRatio,adaptiveRiskPct:challengeDraft.adaptiveRiskPct,adaptiveDrawdownPct:challengeDraft.adaptiveDrawdownPct}} : challenge.state,
    setMode: mode => setChallengeDraft(current => ({...current,mode, rewardRatio:draftReward,adaptiveRiskPct:draftAdaptiveRisk,adaptiveDrawdownPct:draftAdaptiveDrawdown,level: current?.level ?? challenge.state.activeLevel, levelCount: current?.levelCount ?? challenge.state.automation?.levelCount ?? 30})),
    setLevel: level => setChallengeDraft(current => ({...current,level,rewardRatio:draftReward,adaptiveRiskPct:draftAdaptiveRisk,adaptiveDrawdownPct:draftAdaptiveDrawdown, mode: current ? current.mode : challenge.state.automation?.mode ?? null, levelCount: current?.levelCount ?? challenge.state.automation?.levelCount ?? 30})),
    setLevelCount: levelCount => setChallengeDraft(current => ({...current,rewardRatio:draftReward,adaptiveRiskPct:draftAdaptiveRisk,adaptiveDrawdownPct:draftAdaptiveDrawdown,level: current?.level ?? challenge.state.activeLevel, mode: current ? current.mode : challenge.state.automation?.mode ?? null, levelCount})),
    setReward: rewardRatio=>setChallengeDraft(current=>({rewardRatio,adaptiveRiskPct:draftAdaptiveRisk,adaptiveDrawdownPct:draftAdaptiveDrawdown,level:current?.level ?? challenge.state.activeLevel,levelCount:current?.levelCount ?? challenge.state.automation?.levelCount ?? 30,mode:canUseLossStreak(rewardRatio)?(current?.mode || challenge.state.automation?.mode || 'risk'):'risk'})),
    setAdaptiveRisk: adaptiveRiskPct=>setChallengeDraft(current=>({...current,rewardRatio:draftReward,adaptiveRiskPct,adaptiveDrawdownPct:draftAdaptiveDrawdown,level:current?.level ?? challenge.state.activeLevel,levelCount:current?.levelCount ?? challenge.state.automation?.levelCount ?? 30,mode:current?.mode || challenge.state.automation?.mode || 'adaptive'})),
    setAdaptiveDrawdown: adaptiveDrawdownPct=>setChallengeDraft(current=>({...current,rewardRatio:draftReward,adaptiveRiskPct:draftAdaptiveRisk,adaptiveDrawdownPct,level:current?.level ?? challenge.state.activeLevel,levelCount:current?.levelCount ?? challenge.state.automation?.levelCount ?? 30,mode:current?.mode || challenge.state.automation?.mode || 'adaptive'}))
  };
  const [balance, setBalance] = useState(account.balance);
  const platform = account.platform || "Manual";
  const [importFile, setImportFile] = useState(null);
  const [importPreview, setImportPreview] = useState([]);
  const [importError, setImportError] = useState("");
  const [importingTrades, setImportingTrades] = useState(false);
  const [importProgress, setImportProgress] = useState(0);
  const [beCap, setBeCap] = useState(account.breakevenCap);
  const [defaultCommission, setDefaultCommission] = useState(account.defaultCommission || 0);
  const [monthlyGoalPct, setMonthlyGoalPct] = useState(account.monthlyGoalPct || 0);
  const [yearlyGoalPct, setYearlyGoalPct] = useState(account.yearlyGoalPct || 0);
  const [monthlyGoalAmount, setMonthlyGoalAmount] = useState(account.monthlyGoalSource === "amount" ? (account.monthlyGoalAmount || "") : (Math.max(0, financeTotals(account).tradingBalance) * Number(account.monthlyGoalPct || 0) / 100 || ""));
  const [yearlyGoalAmount, setYearlyGoalAmount] = useState(account.yearlyGoalSource === "amount" ? (account.yearlyGoalAmount || "") : (Math.max(0, financeTotals(account).tradingBalance) * Number(account.yearlyGoalPct || 0) / 100 || ""));
  const [monthlyGoalSource, setMonthlyGoalSource] = useState(account.monthlyGoalSource === "amount" ? "amount" : "percentage");
  const [yearlyGoalSource, setYearlyGoalSource] = useState(account.yearlyGoalSource === "amount" ? "amount" : "percentage");
  const [dailyLossLimitPct, setDailyLossLimitPct] = useState(account.dailyLossLimitPct || 0);
  const [monthlyLossLimitPct, setMonthlyLossLimitPct] = useState(account.monthlyLossLimitPct || 0);
  const [positionSizeEnabled, setPositionSizeEnabled] = useState(!!account.positionSizeEnabled);
  const [challengeEnabled, setChallengeEnabled] = useState(isChallengeEnabled(account));
  const [baseCurrency, setBaseCurrency] = useState(account.baseCurrency || "");
  const [defaultRiskPct, setDefaultRiskPct] = useState(account.defaultRiskPct || 1);
  const [defaultStopLossPips, setDefaultStopLossPips] = useState(account.defaultStopLossPips || "");
  const [defaultRiskMethod, setDefaultRiskMethod] = useState(account.defaultRiskMethod || "price");
  const [positionSizing, setPositionSizing] = useState(() => account.positionSizing || { instrumentSpecifications:{}, conversionRates:{} });
  const [sizingInstrument, setSizingInstrument] = useState(DEFAULT_INSTRUMENTS[0]);
  const [financeEnabled, setFinanceEnabled] = useState(!!account.finance?.enabled);
  const [savingsDraft, setSavingsDraft] = useState(account.savingsAccounts || []);
  const [open, setOpen] = useState({ identity: true, balances: false, defaults: true, goals: true, guardrails: true, challenge: true, finance: true, position: true, danger: true });
  const toggle = (section) => setOpen((current) => ({ ...current, [section]: !current[section] }));
  const goalsEnabled = Number(monthlyGoalPct) > 0 || Number(yearlyGoalPct) > 0;
  const guardrailsEnabled = Number(dailyLossLimitPct) > 0 || Number(monthlyLossLimitPct) > 0;
  const multiBalanceTotal = balanceDrafts.reduce((total, item) => total + (Number(item.startingBalance) || 0), 0);
  const selectedBalance = multiBalanceWorkspace ? balanceDrafts.find((item) => item.id === selectedBalanceId) || null : null;
  const savedSelectedBalance = selectedBalance ? (account.balances || []).find((item) => item.id === selectedBalance.id) : null;
  // The first challenge setup stays editable until it is saved. Saving creates
  // its checkpoint and keeps every previously logged trade out of the plan.
  const startingNewBalanceChallenge = !!selectedBalance?.challengeEnabled && !savedSelectedBalance?.challengeEnabled;
  const importedBaseDraft = useRef(null);
  const onImport = async (plan, progress) => {
    importedBaseDraft.current = { id: multiBalanceWorkspace ? selectedBalanceId : activeBalances(account)[0]?.id, base: account.balance,
      starting: (account.balances || []).find(item => item.id === selectedBalanceId)?.startingBalance };
    const ok = await importIntoAccount(plan, progress, multiBalanceWorkspace ? selectedBalanceId : null);
    if (!ok) importedBaseDraft.current = null;
    return ok;
  };
  useEffect(() => {
    const pending = importedBaseDraft.current;
    if (!pending) return;
    const funded = (account.balances || []).find(item => item.id === pending.id);
    if (multiBalanceWorkspace && funded && funded.startingBalance !== pending.starting) {
      setBalanceDrafts(items => items.map(item => item.id === funded.id ? {...item,startingBalance:funded.startingBalance} : item));
      importedBaseDraft.current = null;
    } else if (!multiBalanceWorkspace && account.balance !== pending.base) {
      setBalance(account.balance);importedBaseDraft.current = null;
    }
  }, [account.balances, account.balance, multiBalanceWorkspace]);
  const selectedBalanceIndex = selectedBalance ? balanceDrafts.findIndex((item) => item.id === selectedBalance.id) : -1;
  const activeSizingConfig = multiBalanceWorkspace ? (selectedBalance?.positionSizing || { instrumentSpecifications:{}, conversionRates:{} }) : positionSizing;
  const saveSizingConfig = (next) => multiBalanceWorkspace ? updateSelectedBalance({ positionSizing:next }) : setPositionSizing(next);
  const sizingSpec = getInstrumentSpec(sizingInstrument, activeSizingConfig.instrumentSpecifications || {}).spec;
  const updateSizingSpec = (key, value) => saveSizingConfig({ ...activeSizingConfig, instrumentSpecifications:{ ...(activeSizingConfig.instrumentSpecifications || {}), [normalizeInstrument(sizingInstrument)]:{ ...(activeSizingConfig.instrumentSpecifications?.[normalizeInstrument(sizingInstrument)] || {}), [key]:value, brokerVerified:true } } });
  const settingsBalanceAccount = {...account, balance:Number(balance) || 0, balances:balanceDrafts};
  const settingsLiveBalance = multiBalanceWorkspace
    ? (selectedBalance ? financeTotals(settingsBalanceAccount, selectedBalance.id).tradingBalance : null)
    : financeTotals(settingsBalanceAccount).tradingBalance;
  const settingsChallengeEnabled=multiBalanceWorkspace ? !!selectedBalance?.challengeEnabled : challengeEnabled && Number(balance)>0;
  const settingsChallengeMode=multiBalanceWorkspace
    ? (selectedBalance?.challengeMode || 'risk')
    : (challengeDraft?.mode ?? challenge.state.automation?.mode ?? 'risk');
  const settingsChallengeReward=multiBalanceWorkspace
    ? (selectedBalance?.challengeReward ?? (selectedBalance?.challengeMode==='streak' ? 3.1 : null))
    : (challengeDraft?.rewardRatio ?? challenge.state.automation?.rewardRatio);
  const challengeActivationIssue=settingsChallengeEnabled ? challengeModeActivationRule({mode:settingsChallengeMode,reward:settingsChallengeReward,balance:settingsLiveBalance}) : null;
  const selectedBalanceChallenge = useBalanceChallenge({...selectedBalance || balanceDrafts[0],trades:account.trades,balances:account.balances,financeMovements:account.financeMovements}, userId);
  const selectedBalanceChallengeState = startingNewBalanceChallenge
    ? {...selectedBalanceChallenge.state, settingsLocked:false}
    : selectedBalanceChallenge.state;
  const accountBase = multiBalanceWorkspace ? multiBalanceTotal : (Number(balance) || 0);
  const goalBase = Math.max(0, Number(settingsLiveBalance) || 0);
  const moneyFromPercentage = (percentage, base) => Number(percentage) > 0 && base > 0 ? Number((Number(percentage) * base / 100).toFixed(2)) : "";
  const percentageFromMoney = (amount, base) => Number(amount) > 0 && base > 0 ? Number((Number(amount) / base * 100).toFixed(4)) : "";
  const monthlyTarget = monthlyGoalSource === "amount" ? Number(monthlyGoalAmount) || 0 : goalBase * (Number(monthlyGoalPct) || 0) / 100;
  const yearlyTarget = yearlyGoalSource === "amount" ? Number(yearlyGoalAmount) || 0 : goalBase * (Number(yearlyGoalPct) || 0) / 100;
  const guardrailBase = Math.max(0, Number(settingsLiveBalance) || 0);
  const dailyLimit = guardrailBase * (Number(dailyLossLimitPct) || 0) / 100;
  const monthlyLimit = guardrailBase * (Number(monthlyLossLimitPct) || 0) / 100;
  const setMonthlyGoalPercentage = (value) => { setMonthlyGoalPct(value); setMonthlyGoalAmount(moneyFromPercentage(value, goalBase)); setMonthlyGoalSource("percentage"); };
  const setYearlyGoalPercentage = (value) => { setYearlyGoalPct(value); setYearlyGoalAmount(moneyFromPercentage(value, goalBase)); setYearlyGoalSource("percentage"); };
  const setMonthlyGoalMoney = (value) => { setMonthlyGoalAmount(value); setMonthlyGoalPct(percentageFromMoney(value, goalBase)); setMonthlyGoalSource("amount"); };
  const setYearlyGoalMoney = (value) => { setYearlyGoalAmount(value); setYearlyGoalPct(percentageFromMoney(value, goalBase)); setYearlyGoalSource("amount"); };
  const setDailyLossMoney = (value) => setDailyLossLimitPct(percentageFromMoney(value, guardrailBase));
  const setMonthlyLossMoney = (value) => setMonthlyLossLimitPct(percentageFromMoney(value, guardrailBase));
  const setStartingBalance = (value) => {
    if(challenge.state.settingsLocked) return;
    const nextBase = Number(value) || 0;
    const nextGoalBase = Math.max(0, financeTotals({...account,balance:nextBase}).tradingBalance);
    setBalance(value);
    if (monthlyGoalSource === "amount") setMonthlyGoalPct(percentageFromMoney(monthlyGoalAmount, nextGoalBase)); else setMonthlyGoalAmount(moneyFromPercentage(monthlyGoalPct, nextGoalBase));
    if (yearlyGoalSource === "amount") setYearlyGoalPct(percentageFromMoney(yearlyGoalAmount, nextGoalBase)); else setYearlyGoalAmount(moneyFromPercentage(yearlyGoalPct, nextGoalBase));
  };
  // Keep draft text exactly as typed. Normalising here turned an empty name
  // straight back into “Primary account”, which made editing the field impossible.
  const updateBalanceDraft = (id, patch) => {
    const existing=account.balances?.find(item=>item.id===id);
    if(existing?.challengeEnabled && id===selectedBalance?.id && selectedBalanceChallenge.state.settingsLocked && ['startingBalance','challengeMode','challengeReward','challengeLevelCount','challengeAdaptiveRiskPct','challengeAdaptiveDrawdownPct','challengeEnabled'].some(key=>key in patch)) return;
    setBalanceDrafts((items) => items.map((item) => item.id === id ? { ...item, ...patch } : item));
  };
  const addBalanceDraft = () => {
    const id = `draft-${uid()}`;
    setBalanceDrafts((items) => [...items, normaliseBalance({ id, name: `Account ${items.length + 1}`, startingBalance: 0, baseCurrency, goals: {}, riskSettings: {}, guardrails: {}, challengeEnabled: false, challengeStartingBalance: 0 }, account)]);
    return id;
  };
  const removeBalanceDraft = (id) => setBalanceDrafts((items) => items.length <= 2 ? items : items.filter((item) => item.id !== id));
  const selectWorkspaceType = (nextType, confirmedSingleConversion = false) => {
    if (nextType === workspaceType) return;
    if (nextType === WORKSPACE_TYPES.MULTI_BALANCE && !canUseMultiBalance) return;
    if (nextType === WORKSPACE_TYPES.STANDARD && workspaceType === WORKSPACE_TYPES.MULTI_BALANCE && !confirmedSingleConversion) {
      setSingleConversionWarning(true);
      return;
    }
    if (nextType === WORKSPACE_TYPES.MULTI_BALANCE) {
      const convertingExistingSingle = workspaceType === WORKSPACE_TYPES.STANDARD;
      // A standard workspace already represents one real account. Carry its
      // visible name and starting balance into Account 1 when it becomes multi.
      const primary = normaliseBalance({ ...(balanceDrafts[0] || {}), id: balanceDrafts[0]?.id || `draft-${uid()}`, name: convertingExistingSingle ? (account.name || "Account 1") : (balanceDrafts[0]?.name || "Account 1"), startingBalance: convertingExistingSingle ? (Number(balance) || 0) : (balanceDrafts[0]?.startingBalance ?? (Number(balance) || 0)), baseCurrency, goals: balanceDrafts[0]?.goals && Object.keys(balanceDrafts[0].goals).length ? balanceDrafts[0].goals : { monthlyGoalPct, yearlyGoalPct }, riskSettings: balanceDrafts[0]?.riskSettings && Object.keys(balanceDrafts[0].riskSettings).length ? balanceDrafts[0].riskSettings : { defaultRiskPct, defaultStopLossPips }, guardrails: balanceDrafts[0]?.guardrails && Object.keys(balanceDrafts[0].guardrails).length ? balanceDrafts[0].guardrails : { dailyLossLimitPct, monthlyLossLimitPct }, challengeEnabled, challengeStartingBalance:Number(balance) || 0, challengeMode: challenge.state.automation?.mode || "risk" }, account);
      const drafts = balanceDrafts.length >= 2 ? balanceDrafts : [primary, normaliseBalance({ id: `draft-${uid()}`, name: "Account 2", startingBalance: 0, baseCurrency, goals: {}, riskSettings: {}, guardrails: {}, challengeEnabled: false, challengeStartingBalance: 0 }, account)];
      setBalanceDrafts(drafts);
      setSelectedBalanceId(drafts[0]?.id || null);
      setWorkspaceType(nextType);
      return;
    }
    const primary = balanceDrafts[0];
    if (primary) {
      setStartingBalance(primary.startingBalance);
      setMonthlyGoalPct(primary.goals?.monthlyGoalPct || 0);
      setYearlyGoalPct(primary.goals?.yearlyGoalPct || 0);
      setDailyLossLimitPct(primary.guardrails?.dailyLossLimitPct || 0);
      setMonthlyLossLimitPct(primary.guardrails?.monthlyLossLimitPct || 0);
      setDefaultRiskPct(primary.riskSettings?.defaultRiskPct || 0);
      setDefaultStopLossPips(primary.riskSettings?.defaultStopLossPips || "");
      setChallengeEnabled(!!primary.challengeEnabled);
    }
    setSelectedBalanceId(primary?.id || null);
    setWorkspaceType(nextType);
    setSingleConversionWarning(false);
  };
  const updateSelectedBalance = (patch) => selectedBalance && updateBalanceDraft(selectedBalance.id, patch);
  // Preserve draft text, especially an empty input. Convert only for calculations.
  const scopedMonthlyGoalPct = multiBalanceWorkspace ? (selectedBalance?.goals?.monthlyGoalPct ?? 0) : monthlyGoalPct;
