                    <span className="tj-news-day-title"><small>{DOW_FULL[d.getDay()].slice(0,3)}</small><strong>{String(d.getDate()).padStart(2,"0")}</strong><i>{byDay[key].map((e,i)=><b key={i} className={`tj-impact-dot tj-impact-dot-${e.impact}`}/>)}</i></span>
                    {isToday && <span className="tj-daytag tj-daytag-today">TODAY</span>}
                    {isPast && !isToday && <span className="tj-daytag tj-daytag-past">PAST</span>}
